-- real (from migration 0001)
CREATE INDEX ix_deliveries_due ON deliveries (next_attempt_at)
 WHERE status IN ('pending', 'in_flight');

-- illustrative (NOT in this repo): monthly partitions for the attempt log
CREATE TABLE delivery_attempts (
  id bigint GENERATED ALWAYS AS IDENTITY, delivery_id bigint NOT NULL, attempt int NOT NULL,
  started_at timestamptz NOT NULL DEFAULT now(), ...,
  PRIMARY KEY (id, started_at)
) PARTITION BY RANGE (started_at);
CREATE TABLE delivery_attempts_2026_11 PARTITION OF delivery_attempts
  FOR VALUES FROM ('2026-11-01') TO ('2026-12-01');
-- retention: DROP TABLE delivery_attempts_2026_08;

